import {Component, OnInit} from '@angular/core'; // Import OnInit
import {Router, RouterModule, ActivatedRoute} from '@angular/router'; // Import RouterModule, Router, and ActivatedRoute
import { AuthService } from '../services/auth.service'; // Assuming you have an AuthService
import { CartService } from '../services/cart.service'; // Assuming you have a CartService
import { CommonModule } from '@angular/common'; // Import CommonModule
import { Observable } from 'rxjs';
import { User } from '../models/user.model'; // Adjust path as necessary

@Component({
    selector: 'app-header',
    standalone: true, // Make standalone
    imports: [
        RouterModule,
        CommonModule // Add CommonModule here
    ], // Add RouterModule for routerLink
    templateUrl: './header.component.html',
    styleUrls: ['./header.component.css']
})
export class HeaderComponent implements OnInit { // Implement OnInit
    currentSearchTerm: string = ''; // Property to hold search term for display
    isLoggedIn$: Observable<boolean>;
    currentUser$: Observable<User | null>;

    constructor(
        private router: Router,
        private route: ActivatedRoute,
        public authService: AuthService,
        public cartService: CartService
    ) {
        this.isLoggedIn$ = this.authService.isLoggedIn$;
        this.currentUser$ = this.authService.currentUser$;
    } // Inject ActivatedRoute

    ngOnInit(): void {
        this.route.queryParams.subscribe(params => {
            this.currentSearchTerm = params['search'] || '';
        });
    }

    onSearch(eventOrSearchTerm: Event | string): void {
        let searchTerm: string;
        if (typeof eventOrSearchTerm === 'string') {
            searchTerm = eventOrSearchTerm;
        } else {
            const inputElement = eventOrSearchTerm.target as HTMLInputElement;
            searchTerm = inputElement.value;
        }

        const trimmedSearchTerm = searchTerm.trim();

        if (trimmedSearchTerm) {
            this.router.navigate(['/products'], {
                queryParams: {search: trimmedSearchTerm},
                queryParamsHandling: 'merge' // Preserve other query params
            });
        } else {
            // If search term is empty, remove it from query params
            this.router.navigate(['/products'], {
                queryParams: {search: null}, // Setting to null removes the param
                queryParamsHandling: 'merge' // Preserve other query params
            });
        }
    }

    logout(): void {
        this.authService.logout();
        this.router.navigate(['/login']); // Redirect to login page after logout
    }
}
<header class="flex items-center justify-between whitespace-nowrap border-b border-solid border-b-slate-200 px-10 py-4 shadow-sm">
    <div class="flex items-center gap-10">
        <div class="flex items-center gap-3 text-[#141414]">
            <a routerLink="/home"
               class="flex items-center gap-3 text-[#141414] hover:text-[#eb6c28] transition-colors cursor-pointer">
                <div class="size-6 text-[#141414]">
                    <svg fill="none" viewBox="0 0 48 48" xmlns="http://www.w3.org/2000/svg">
                        <path d="M4 42.4379C4 42.4379 14.0962 36.0744 24 41.1692C35.0664 46.8624 44 42.2078 44 42.2078L44 7.01134C44 7.01134 35.068 11.6577 24.0031 5.96913C14.0971 0.876274 4 7.27094 4 7.27094L4 42.4379Z"
                              fill="currentColor"></path>
                    </svg>
                </div>
                <h2 class="text-[#141414] text-xl font-bold leading-tight tracking-[-0.015em]">Backpack Co.</h2>
            </a>
        </div>
        <nav class="flex items-center gap-8">
            <a class="text-slate-700 hover:text-[#141414] text-sm font-medium leading-normal transition-colors"
               routerLink="/products">New Arrivals</a>
            <a class="text-slate-700 hover:text-[#141414] text-sm font-medium leading-normal transition-colors"
               routerLink="/products">Featured</a>
            <a class="text-slate-700 hover:text-[#141414] text-sm font-medium leading-normal transition-colors"
               routerLink="/products">Men</a>
            <a class="text-slate-700 hover:text-[#141414] text-sm font-medium leading-normal transition-colors"
               routerLink="/products">Women</a>
            <a class="text-slate-700 hover:text-[#141414] text-sm font-medium leading-normal transition-colors"
               routerLink="/products">Accessories</a>
            <a class="text-slate-700 hover:text-[#141414] text-sm font-medium leading-normal transition-colors"
               routerLink="/products">Sale</a>
        </nav>
    </div>

    <!-- Middle Section: Username -->
    <div class="flex-1 text-center px-4">
        <span *ngIf="(isLoggedIn$ | async) && (currentUser$ | async) as user" class="text-lg font-medium bg-indigo-500 text-white px-4 py-2 rounded-lg shadow-md">
            Welcome, {{ user.name }}
        </span>
    </div>

    <div class="flex items-center gap-4"> <!-- MODIFIED: Was flex flex-1 justify-end gap-4 -->
        <label class="flex flex-col min-w-48 !h-10 max-w-xs">
            <div class="flex w-full flex-1 items-stretch rounded-lg h-full">
                <div class="text-slate-500 flex border border-slate-300 bg-slate-50 items-center justify-center pl-3 rounded-l-lg border-r-0"
                     data-icon="MagnifyingGlass" data-size="20px" data-weight="regular" (click)="onSearch(searchInput.value)">
                    <svg fill="currentColor" height="20px" viewBox="0 0 256 256" width="20px"
                         xmlns="http://www.w3.org/2000/svg">
                        <path d="M229.66,218.34l-50.07-50.06a88.11,88.11,0,1,0-11.31,11.31l50.06,50.07a8,8,0,0,0,11.32-11.32ZM40,112a72,72,0,1,1,72,72A72.08,72.08,0,0,1,40,112Z"></path>
                    </svg>
                </div>
                <input #searchInput class="form-input flex w-full min-w-0 flex-1 resize-none overflow-hidden rounded-r-lg text-[#141414] focus:outline-none focus:ring-2 focus:ring-[#141414] focus:border-transparent border border-slate-300 bg-slate-50 h-full placeholder:text-slate-500 px-3 text-sm font-normal leading-normal border-l-0"
                       placeholder="Search products..." (keyup.enter)="onSearch($event)" [value]="currentSearchTerm" />
            </div>
        </label>
        <div class="flex gap-2">
            <button aria-label="Wishlist"
                    class="flex max-w-[480px] cursor-pointer items-center justify-center overflow-hidden rounded-lg h-10 bg-slate-100 hover:bg-slate-200 text-[#141414] gap-2 text-sm font-bold leading-normal tracking-[0.015em] min-w-0 px-3 transition-colors">
                <div class="text-[#141414]" data-icon="Heart" data-size="20px" data-weight="regular">
                    <svg fill="currentColor" height="20px" viewBox="0 0 256 256" width="20px"
                         xmlns="http://www.w3.org/2000/svg">
                        <path d="M178,32c-20.65,0-38.73,8.88-50,23.89C116.73,40.88,98.65,32,78,32A62.07,62.07,0,0,0,16,94c0,70,103.79,126.66,108.21,129a8,8,0,0,0,7.58,0C136.21,220.66,240,164,240,94A62.07,62.07,0,0,0,178,32ZM128,206.8C109.74,196.16,32,147.69,32,94A46.06,46.06,0,0,1,78,48c19.45,0,35.78,10.36,42.6,27a8,8,0,0,0,14.8,0c6.82-16.67,23.15-27,42.6-27a46.06,46.06,0,0,1,46,46C224,147.61,146.24,196.15,128,206.8Z"></path>
                    </svg>
                </div>
            </button>
            <button aria-label="Shopping Cart" id="cart-icon" routerLink="/cart"
                    class="flex max-w-[480px] cursor-pointer items-center justify-center overflow-hidden rounded-lg h-10 bg-slate-100 hover:bg-slate-200 text-[#141414] gap-2 text-sm font-bold leading-normal tracking-[0.015em] min-w-0 px-3 transition-colors">
                <div class="text-[#141414]" data-icon="ShoppingBag" data-size="20px" data-weight="regular">
                    <svg fill="currentColor" height="20px" viewBox="0 0 256 256" width="20px"
                         xmlns="http://www.w3.org/2000/svg">
                        <path d="M216,40H40A16,16,0,0,0,24,56V200a16,16,0,0,0,16,16H216a16,16,0,0,0,16-16V56A16,16,0,0,0,216,40Zm0,160H40V56H216V200ZM176,88a48,48,0,0,1-96,0,8,8,0,0,1,16,0,32,32,0,0,0,64,0,8,8,0,0,1,16,0Z"></path>
                    </svg>
                </div>
            </button>
        </div>
        <div class="flex gap-2">
            <!-- Conditional rendering for Login/Signup or Logout -->
            <ng-container *ngIf="!(isLoggedIn$ | async); else loggedInUser">
                <button type="button"
                        class="text-white bg-blue-700 hover:bg-blue-800 focus:ring-4 focus:outline-none focus:ring-blue-300 font-medium rounded-lg text-sm px-4 py-2 text-center dark:bg-blue-600 dark:hover:bg-blue-700 dark:focus:ring-blue-800"
                        routerLink="/login">Login</button>
                <button type="button"
                        class="ml-2 text-white bg-green-700 hover:bg-green-800 focus:ring-4 focus:outline-none focus:ring-green-300 font-medium rounded-lg text-sm px-4 py-2 text-center dark:bg-green-600 dark:hover:bg-green-700 dark:focus:ring-green-800"
                        routerLink="/signup">Sign Up</button>
            </ng-container>
            <ng-template #loggedInUser>
                <!-- Username is now in the middle. Only Logout button here -->
                <button type="button"
                        class="text-white bg-red-700 hover:bg-red-800 focus:ring-4 focus:outline-none focus:ring-red-300 font-medium rounded-lg text-sm px-4 py-2 text-center dark:bg-red-600 dark:hover:bg-red-700 dark:focus:ring-red-800"
                        (click)="logout()">Logout</button>
            </ng-template>
        </div>
        <div class="bg-center bg-no-repeat aspect-square bg-cover rounded-full size-10 border border-slate-200 shadow-sm"
             style='background-image: url("https://lh3.googleusercontent.com/aida-public/AB6AXuCguDLTvaA3rGVWfIzTur8-dq07VykbhXLkya969OgJFK5UrRSJMA4VwgJyXL80FD2taBlSbjCnwuDT3V07ZOxruxNUpBPEdZ63gm86vYQm2UBHIvtSgh1b8_KOgZkf_KJDwkWghSKrXyJB_WYogjbn9AgJ0H34s2NL5C4u55FQtw_Yn1-R9MT5asAoREG07Xz8dn-D0k3L2OMfMiMIi-iDsp_fx3m_BmOtqoNsa_R3LTLOyrtbQEQ-5q6wW6Xddp0va6omrHVoXtWh");'>
        </div>
    </div>
</header>
